const d = $input.first().json;
const src = d.rateData || d;
const limits = src.rate_limits || {};
const fiveHour = limits.five_hour || {};
const sevenDay = limits.seven_day || {};
const ctxWindow = src.context_window || {};
const cost = src.cost || {};

const nowSec = Date.now() / 1000;

const used5h = fiveHour.used_percentage || 0;
const used7d = sevenDay.used_percentage || 0;
const rem5h = 100 - used5h;
const rem7d = 100 - used7d;

function hoursLeft(ts) {
  if (!ts) return null;
  return Math.max(0, (ts - nowSec) / 3600);
}

function fmtH(h) {
  return h === null ? '?' : h.toFixed(1) + 'h';
}

const hrs5h = hoursLeft(fiveHour.resets_at);
const hrs7d = hoursLeft(sevenDay.resets_at);

// Estimate tokens remaining in 5h window using current session as reference.
// session_tokens / used_pct gives estimated total capacity; multiply by remaining_pct.
const totalTok = (ctxWindow.total_input_tokens || 0) + (ctxWindow.total_output_tokens || 0);
let tokenEst = '';
if (totalTok > 0 && used5h > 0) {
  const remTokens = (totalTok / used5h) * rem5h;
  tokenEst = ` (~${(remTokens / 1000000).toFixed(1)}M tokens)`;
}

const usd = cost.total_cost_usd;
const sessionLine = totalTok > 0
  ? `Session: ${(totalTok / 1000).toFixed(0)}K tokens${usd != null ? ` | $${usd.toFixed(2)}` : ''}`
  : '';

const lines = [
  '\u{1F4CA} *Claude Code Rate Limits*',
  '',
  `5h: *${rem5h.toFixed(0)}%* left${tokenEst} \u00b7 resets in ${fmtH(hrs5h)}`,
  `7d: *${rem7d.toFixed(0)}%* left \u00b7 resets in ${fmtH(hrs7d)}`,
];
if (sessionLine) lines.push('', sessionLine);

return [{ json: { message: lines.join('\n') } }];
